'use strict';
const solutions=[{label:"ON-SITE GENERATION",title:"More of your own energy used on site.",text:"Compare your solar PV generation profile with your business's load. Understand when surplus can be stored and when energy will need to be purchased from the grid.",task:"Coordinate generation, load and storage availability.",logic:"A unified energy balance, forecast and plan for using available assets.",audit:"Load profile, solar PV capacity, export limits and BESS availability."},{label:"STORAGE MANAGEMENT",title:"A battery guided by economics. With the reserve you need.",text:"Shift energy purchases between hours when the tariff and technical conditions make it worthwhile. Define backup reserve and allowable battery use separately.",task:"Reduce expensive purchases while preserving the agreed reserve.",logic:"A charging and discharging schedule that accounts for price, efficiency, load and limits.",audit:"Usable capacity, power, SoC, access to the BMS and inverter commands."},{label:"ENERGY METERING",title:"Understand your site through its data. In one shared view.",text:"Bring consumption and generation points into one consistent picture. Shared data helps the energy manager control operating modes and executives understand the cost structure.",task:"Consolidate scattered readings and understand the energy balance.",logic:"Data collection, history, period comparisons and deviation analysis.",audit:"Metering diagram, meter inventory, interfaces and available data quality."}];
const tabs=[...document.querySelectorAll('[data-solution]')];function selectSolution(i,focus=false){tabs.forEach((b,j)=>{b.setAttribute('aria-selected',String(i===j));b.tabIndex=i===j?0:-1});const s=solutions[i];for(const key of ['label','title','text','task','logic','audit'])document.getElementById('solution-'+key).textContent=s[key];document.getElementById('solution-content').setAttribute('aria-labelledby','tab-'+i);document.getElementById('solution-content').dataset.scenario=String(i);document.querySelector('.scenario-asset-map>span').textContent=["SOLAR PV",'BESS',"Metering"][i];if(focus)tabs[i].focus()}tabs.forEach((b,i)=>{b.addEventListener('click',()=>selectSolution(i));b.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();selectSolution(e.key==='Home'?0:e.key==='End'?2:(i+(e.key==='ArrowRight'?1:2))%3,true)}})});selectSolution(0);
const menu=document.querySelector('.menu-toggle'),nav=document.getElementById('navigation');
const compactNavigation=window.matchMedia('(max-width:1020px)');
const menuOpenLabel=menu.getAttribute('aria-label');
const menuLinks=[...nav.querySelectorAll('a')];
function setMenuOpen(open,restoreFocus=false){
 const expanded=compactNavigation.matches&&open;
 nav.classList.toggle('open',expanded);
 menu.setAttribute('aria-expanded',String(expanded));
 menu.setAttribute('aria-label',expanded?"Close menu":menuOpenLabel);
 nav.inert=compactNavigation.matches&&!expanded;
 if(restoreFocus)menu.focus();
}
menu.addEventListener('click',event=>{
 const open=menu.getAttribute('aria-expanded')!=='true';
 setMenuOpen(open);
 if(open&&event.detail===0)menuLinks[0].focus();
});
menuLinks.forEach(link=>link.addEventListener('click',()=>{
 menuLinks.forEach(other=>other.removeAttribute('aria-current'));
 link.setAttribute('aria-current','location');
 setMenuOpen(false);
}));
document.addEventListener('click',event=>{
 if(menu.getAttribute('aria-expanded')==='true'&&!nav.contains(event.target)&&!menu.contains(event.target))setMenuOpen(false);
});
document.addEventListener('keydown',event=>{
 if(menu.getAttribute('aria-expanded')!=='true')return;
 if(event.key==='Escape'){event.preventDefault();setMenuOpen(false,true);}
 if(event.key==='Tab'){
  if(!event.shiftKey&&document.activeElement===menu){event.preventDefault();menuLinks[0].focus();}
  else if(event.shiftKey&&document.activeElement===menuLinks[0]){event.preventDefault();menu.focus();}
  else if(!event.shiftKey&&document.activeElement===menuLinks[menuLinks.length-1]){event.preventDefault();menu.focus();}
 }
});
document.querySelector('.header').addEventListener('focusout',event=>{
 if(menu.getAttribute('aria-expanded')==='true'&&event.relatedTarget&&!document.querySelector('.header').contains(event.relatedTarget))setMenuOpen(false);
});
compactNavigation.addEventListener('change',()=>setMenuOpen(false));
setMenuOpen(false);
const prices=[3.2,2.9,2.6,2.4,2.5,2.8,3.4,4.3,5.1,5.4,5.2,4.6,4.1,3.9,4.4,5.3,6.7,7.6,8.2,8,7.4,6.2,4.8,3.8],chart=document.getElementById('price-chart');
function kind(h){return h<6?'charge':h>=17&&h<=21?'discharge':'hold'}prices.forEach((price,h)=>{const b=document.createElement('button');b.style.height=(price/9*100)+'%';b.dataset.kind=kind(h);b.title=`${String(h).padStart(2,'0')}:00 — ${formatDemoNumber(price)} ₴/kWh`;b.setAttribute('aria-label',b.title);b.setAttribute('aria-pressed','false');b.addEventListener('click',()=>setHour(h));chart.appendChild(b)});
function setHour(h){if(typeof stopDayPlayback==='function'&&!dayPlaybackTick)stopDayPlayback();const time=String(h).padStart(2,'0')+':00';document.getElementById('hour').value=h;document.getElementById('hour-label').textContent=time;document.getElementById('selected-hour').textContent=time;document.getElementById('decision-price').textContent=formatDemoNumber(prices[h])+' ₴';const k=kind(h);document.getElementById('decision-title').textContent=k==='charge'?"Charge at a lower price":k==='discharge'?"Displace expensive purchases":h>=22?"Preserve reserve":"Maintain flexibility";document.getElementById('decision-text').textContent=k==='charge'?"In this example, the night-time price is lower. The plan schedules charging if the expected price difference covers losses and battery wear.":k==='discharge'?"Stored energy covers part of the load during expensive hours. Discharging is limited by power and the agreed reserve.":h>=22?"In this example, the discharge period has ended. The battery maintains the agreed reserve until the next planning cycle.":"In the daytime scenario, using solar generation on site takes priority. Surplus can charge the battery if its condition permits.";[...chart.children].forEach((b,i)=>b.setAttribute('aria-pressed',String(i===h)));document.dispatchEvent(new CustomEvent('operion:hour',{detail:{hour:h,kind:k}}))}document.getElementById('hour').addEventListener('input',e=>setHour(Number(e.target.value)));setHour(18);
document.getElementById('year').textContent=new Date().getFullYear();

// Product demonstration. Explicit scenarios, no live telemetry or equipment commands.
const demoPhases=[{time:"02:00 / NIGHT",solar:0,load:110,grid:190,soc:38,battery:"Charging 80 kW",badge:"SHIFTING PURCHASES",action:"Build up energy for more expensive hours.",reason:"In the demo plan, the grid supplies 110 kW of load and 80 kW of charging. Viability depends on the tariff, losses and battery wear.",balance:"Balance: 190 = 110 + 80 kW",description:"The grid supplies 190 kW: the business consumes 110 kW and 80 kW charges the battery.",solarActive:false,gridActive:true,reverse:false},{time:"12:00 / DAYTIME",solar:240,load:180,grid:0,soc:62,battery:"Charging: 60 kW",badge:"ON-SITE GENERATION",action:"Use the sun. Store the surplus.",reason:"Generation exceeds the current load. In this scenario, the site uses 180 kW and 60 kW charges the BESS.",balance:"Balance: 240 = 180 + 60 kW",description:"Solar PV generates 240 kW: the business consumes 180 kW and 60 kW charges the battery. Grid purchases: 0 kW.",solarActive:true,gridActive:false,reverse:false},{time:"18:00 / PEAK",solar:35,load:180,grid:0,soc:74,battery:"Discharging 145 kW",badge:"DISPLACING EXPENSIVE PURCHASES",action:"Cover the load with BESS energy.",reason:"35 kW from solar PV and 145 kW from the battery cover 180 kW of consumption. Discharging is limited by the agreed reserve and power.",balance:"Balance: 35 + 145 = 180 kW",description:"Solar PV supplies 35 kW, the battery delivers 145 kW and the business consumes 180 kW. Grid purchases: 0 kW.",solarActive:true,gridActive:false,reverse:true}];
const phaseButtons=[...document.querySelectorAll('[data-phase]')];let demoPhase=1,demoTimer=null;const reducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)');
function showDemoPhase(i){demoPhase=i;const p=demoPhases[i];for(const key of ['solar','load','grid','soc'])document.getElementById('demo-'+key).textContent=p[key];for(const key of ['solar','load','grid'])document.getElementById('node-'+key).textContent=p[key]+" kW";document.getElementById('node-battery').textContent=p.battery;for(const key of ['time','badge','action','reason','balance'])document.getElementById('demo-'+key).textContent=p[key];document.getElementById('flow-desc').textContent=p.description;document.getElementById('demo-soc-bar').style.width=p.soc+'%';document.getElementById('path-solar').classList.toggle('flow-inactive',!p.solarActive);document.getElementById('path-grid').classList.toggle('flow-inactive',!p.gridActive);document.getElementById('path-battery').classList.toggle('flow-reverse',p.reverse);phaseButtons.forEach((b,j)=>b.setAttribute('aria-pressed',String(i===j)));document.dispatchEvent(new CustomEvent('operion:phase',{detail:{phase:i}}));}
const demoPlay=document.getElementById('demo-play');function stopDemo(){if(demoTimer)clearInterval(demoTimer);demoTimer=null;demoPlay.setAttribute('aria-pressed','false');demoPlay.setAttribute('aria-label',"Start automatic scenario playback");demoPlay.textContent="▶ Auto-play"}function startDemo(){if(demoTimer)return;demoPlay.setAttribute('aria-pressed','true');demoPlay.setAttribute('aria-label',"Pause automatic scenario changes");demoPlay.textContent="Ⅱ Pause";demoTimer=setInterval(()=>showDemoPhase((demoPhase+1)%3),6500)}phaseButtons.forEach((b,i)=>b.addEventListener('click',()=>{stopDemo();showDemoPhase(i)}));demoPlay.addEventListener('click',()=>demoTimer?stopDemo():startDemo());document.addEventListener('visibilitychange',()=>{if(document.hidden)stopDemo()});reducedMotion.addEventListener('change',e=>{if(e.matches)stopDemo()});showDemoPhase(1);
const businessTypes=[{category:"MANUFACTURING BUSINESSES",title:"Energy should follow your production schedule.",problem:"Shifts, different production areas and on-site generation create a complex consumption profile. A manual battery schedule does not always match the actual load.",person:"Energy manager · technical director · finance lead",value:"One view of incoming supplies, generation and assets. A BESS operating plan based on the production profile, tariff and agreed reserve.",scenario:"Use solar PV for self-consumption and shift some energy purchases between hours, without interfering with the production process.",data:"Hourly consumption profile, shift schedule, solar PV/BESS capacity, connection limits and available interfaces."},{category:"LOGISTICS AND COLD CHAINS",title:"Cooling cannot wait. Align reserve and costs.",problem:"Cold stores and warehouses have sustained loads. Economical battery operation must account for critical consumption and backup reserve.",person:"Facility manager · energy manager · operations team",value:"Meter refrigeration loads and the overall energy balance. See BESS status clearly and plan its use with a separate reserve constraint.",scenario:"Solar PV covers daytime load, while BESS shifts some purchases to more favourable hours. Backup autonomy is assessed separately rather than assumed.",data:"Critical load, required backup duration, inverter power, battery capacity and actual operating conditions."},{category:"AGRICULTURE AND PROCESSING",title:"Seasonal loads need a flexible plan.",problem:"Consumption at a grain storage or processing facility changes during the season. Year-round fixed settings may not match actual operation.",person:"Business owner · chief engineer · energy manager",value:"Consumption history by period, comparison with generation and planning of available energy assets around the seasonal profile.",scenario:"On-site solar energy for daytime processes, BESS charging during agreed periods and discharging to meet site needs. Production lines are not switched without a separate engineering project.",data:"Seasonal schedules, main equipment operating patterns, generation sources, tariff and metering capabilities."},{category:"RETAIL AND SHOPPING FACILITIES",title:"Align daytime generation with evening consumption.",problem:"Solar generation, refrigeration, lighting and evening activity create different load profiles. Data often remains in separate systems.",person:"Site director · network energy manager · finance manager",value:"An energy balance, period comparisons and a BESS usage plan. Executives see the cost breakdown; engineers see the conditions and scenario limits.",scenario:"Use on-site generation and displace some expensive evening purchases when the tariff and load profile make it economical.",data:"Opening hours, daytime and evening load, metering diagram, tariff, existing solar PV and storage."},{category:"COMMERCIAL PROPERTY",title:"Turn scattered readings into a building-wide balance.",problem:"Multiple incoming supplies, shared areas and different user schedules complicate energy metering in offices, hotels and complexes.",person:"Property management · operations team · property owner",value:"Energy metering at agreed points, generation and consumption history, and period comparisons. Where controllable assets are available, add a separate optimisation module.",scenario:"Start with data collection and deviation monitoring. After assessing the profile, add an agreed solar PV and BESS operating plan.",data:"Incoming supply diagram, meter inventory, shared loads and interfaces. Energy submetering does not replace tenant billing."},{category:"MULTI-SITE PORTFOLIOS",title:"A shared approach to assessment. Site-specific rules.",problem:"Separate apps, different inverters and varying tariffs make it harder to compare sites and identify the causes of deviations.",person:"Group energy manager · technical director · network director",value:"A consistent approach to collecting readings, analysing periods and defining scenarios. The scope of consolidation and integrations is specified in the project.",scenario:"Pilot at one site and validate the data and impact. Then roll out the agreed solution, accounting for each site's specific conditions.",data:"Site inventory, device models, access permissions, data quality and tariffs. Centralised control capability is verified separately."}];
const businessButtons=[...document.querySelectorAll('[data-business]')];function selectBusiness(i,focus=false){businessButtons.forEach((b,j)=>{b.setAttribute('aria-selected',String(j===i));b.tabIndex=j===i?0:-1});const b=businessTypes[i];for(const k of ['category','title','problem','person','value','scenario','data'])document.getElementById('business-'+k).textContent=b[k];const panel=document.getElementById('business-panel');panel.setAttribute('aria-labelledby','business-tab-'+i);panel.classList.remove('content-enter');void panel.offsetWidth;panel.classList.add('content-enter');if(focus)businessButtons[i].focus()}
businessButtons.forEach((b,i)=>{b.addEventListener('click',()=>selectBusiness(i));b.addEventListener('keydown',e=>{if(['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();selectBusiness(e.key==='Home'?0:e.key==='End'?5:(i+(e.key==='ArrowRight'?1:5))%6,true)}})});selectBusiness(0);
// Progressive scroll reveals: content stays available when motion is reduced or observers are unsupported.
if(!reducedMotion.matches&&'IntersectionObserver' in window){const sections=[...document.querySelectorAll('.module-grid article,.steps article,.software-deliverables p')];sections.forEach(el=>el.classList.add('reveal-item'));document.documentElement.classList.add('has-reveal');const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('is-visible');observer.unobserve(e.target)}}),{threshold:.08});sections.forEach(el=>observer.observe(el));}
